'use strict';
(function(){const T=JourneyTraits,oldIcon=traitIcon;traitIcon=function(id){return globalThis.JourneyTraitArt?.[id]?'trait:'+id:T.D[id]?.icon||oldIcon(id)||'star';};let previousModal=null,categoryReturn=null,previewCounts=null,filterPositions=[];
function label(d){return L(d.en,d.pt);}function countsNow(){if(battle?.traits54)return battle.traits54.counts[0];if(!S)return{};if(selected){const id=selectedUid();if(id)return G.traitPreview(S,id).after;}return G.counts(S.board.filter(Boolean).map(id=>G.card(S,id)));}
traitRibbon=function(){const n=countsNow();return '<div class="trait-ribbon traits54-ribbon">'+Object.entries(T.categories).map(([id,d])=>{const active=Object.values(T.D).filter(t=>t.category===id&&T.tier(n,t.id)>0).length;return '<button class="traits54-category" data-act="traits54-category" data-id="'+id+'">'+Icon({faction:'units',attribute:'sword',temperament:'star'}[id])+'<span>'+label(d)+'</span><b>'+active+'</b></button>';}).join('')+'</div>';};
function remember(){const el=document.querySelector('#overlay>.modal');if(el){const copy=el.cloneNode(true);copy.querySelector('.close')?.remove();previousModal={html:copy.innerHTML,cls:el.className};}else previousModal=null;}
function back(){previewCounts=null;if(categoryReturn){const id=categoryReturn;category(id);return;}if(previousModal){const p=previousModal;previousModal=null;openModal(p.html);document.querySelector('#overlay>.modal').className=p.cls;}else closeModal();}
function effect(d){return esc(L(d.desc,d.descPT)).replace(/([+−–-]?\d+(?:[.,]\d+)?%?)/g,'<strong>$1</strong>');}
function detailTrait(id){const d=T.D[id];if(!d)return;const counts=previewCounts||countsNow(),n=counts[id]||0,k=T.tier(counts,id);journeyPanel(label(d),'<div class="trait-focus"><div class="trait-focus-icon">'+Icon(traitIcon(id))+'</div><div><span class="trait-kind">'+label(T.categories[d.category])+'</span><p class="trait-effect">'+effect(d)+'</p></div></div><div class="trait-progress">'+(d.thresholds.length?'<span>'+(previewCounts?L('In this deck','Neste deck'):L('In the field','Em campo'))+' <b>'+n+'</b></span><span>'+L('Tiers','Patamares')+' <b>'+d.thresholds.join(' / ')+'</b></span><span class="'+(k?'active':'')+'">'+(k?(previewCounts?L('Potential tier ','Patamar potencial '):L('Active tier ','Patamar ativo '))+k:L('Inactive','Inativo'))+'</span>':L('Faction identity','Identificação de facção'))+'</div><details class="trait-rules"><summary>'+L('How counting works','Como funciona a contagem')+'</summary><p>'+L('Count different characters in the field. Repeated copies, fusion copies and reserve units do not add to the count. The higher tier replaces the lower. Battle tiers stay fixed for the round.','Conte personagens diferentes em campo. Cópias repetidas, constituintes de fusão e unidades no banco não aumentam a contagem. O patamar maior substitui o menor. No combate, o patamar fica fixo durante a rodada.')+'</p></details>',metaButton('traits54-back',L('Back','Voltar'),'','primary'));}
function category(id){previewCounts=null;previousModal=null;categoryReturn=id;const n=countsNow(),all=Object.values(T.D).filter(d=>d.category===id);journeyPanel(label(T.categories[id]),'<div class="traits54-list">'+all.map(d=>'<button data-act="traits54-open" data-id="'+d.id+'" class="'+(T.tier(n,d.id)?'active':'')+'">'+Icon(traitIcon(d.id))+'<span><b>'+esc(label(d))+'</b><small>'+effect(d)+'</small></span><em class="trait-count">'+(n[d.id]||0)+(d.thresholds.length?' / '+d.thresholds.join('·'):'')+'</em></button>').join('')+'</div>',metaButton('close',L('Back','Voltar'),'','primary'));}
// Borrowed deck preview: cards first, then its starting relic, then synergies.
const preview=deckPreview;deckPreview=function(id){preview(id);const modal=document.querySelector('#overlay>.modal');if(!modal?.querySelector('.deck-preview-cards'))return;const traits=modal.querySelector('.deck-preview-traits'),note=modal.querySelector('.deck-trait-note'),footer=modal.querySelector('.deck-confirm');if(note)note.textContent=L('Deck traits & synergies','Traits e sinergias do deck');if(note)modal.insertBefore(note,footer);if(traits)modal.insertBefore(traits,footer);const body=document.createElement('div');body.className='deck-preview-scroll';for(const el of [...modal.children])if(!el.classList.contains('close')&&!el.classList.contains('browse-heading')&&el!==footer)body.append(el);modal.insertBefore(body,footer);modal.classList.add('deck-preview-modal');if(footer)footer.classList.add('deck-preview-footer');};
const collection=collectionView;collectionView=function(){const rows=[...document.querySelectorAll('.meta-screen .meta-filters')],top=document.querySelector('#screen-content')?.scrollTop||0;if(rows.length)filterPositions=rows.map(el=>el.scrollLeft);const was=activeMetaScreen==='collection';collection();const apply=()=>{[...document.querySelectorAll('.meta-screen .meta-filters')].forEach((el,i)=>el.scrollLeft=filterPositions[i]||0);if(was&&document.querySelector('#screen-content'))document.querySelector('#screen-content').scrollTop=top;};apply();requestAnimationFrame(apply);for(const el of document.querySelectorAll('.collection-entry')){const id=el.querySelector('[data-act="meta-info"]')?.dataset.id,a=T.assignments[id],caption=el.querySelector(':scope>small');if(a&&caption)caption.textContent=a.faction+(G.BY[id].order?' · '+(G.BY[id].order==='blackfang'?'Blackfang':G.BY[id].order==='ironbound'?'Grand Union':'Dawncrest'):'');}};
const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),d=el?.dataset;if(!d)return guard(e);if(d.act==='close'&&(previewCounts||previousModal||categoryReturn)&&document.querySelector('#overlay .trait-focus')){e.preventDefault();e.stopImmediatePropagation();back();return true;}if(d.act!=='trait'&&!d.act.startsWith('traits54-'))return guard(e);if(e.type!=='click'&&!(e.type==='keydown'&&['Enter',' '].includes(e.key)))return guard(e);e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return true;if(d.act==='traits54-run'){categoryReturn=null;remember();previewCounts=G.counts(JourneyPlaytest.units(S));detailTrait(d.id);}else if(d.act==='traits54-preview'){categoryReturn=null;remember();const deck=G.DECKS.find(d=>d.id===previewDeckId);previewCounts=G.counts(G.deckCards(deck).map(type=>({type,level:0})));detailTrait(d.id);}else if(d.act==='trait'){previewCounts=null;categoryReturn=null;remember();detailTrait(d.id);}else if(d.act==='traits54-category')category(d.id);else if(d.act==='traits54-open')detailTrait(d.id);else if(d.act==='traits54-back')back();return true;};
})();
